gdi(a){return"\u041f\u043e\u0442\u0432\u044a\u0440\u0434\u0435\u0442\u0435"},
geA(){return"\u041f\u043e\u0442\u0440\u0435\u0431\u0438\u0442\u0435\u043b\u044f\u0442 \u0438\u043b\u0438 \u043f\u0430\u0440\u043e\u043b\u0430\u0442\u0430 \u043d\u0435 \u0441\u0430 \u0432\u0430\u043b\u0438\u0434\u043d\u0438. \u041c\u043e\u043b\u044f, \u0441\u0432\u044a\u0440\u0436\u0435\u0442\u0435 \u0441\u0435 \u0441\u044a\u0441 \u0441\u0432\u043e\u044f \u0440\u044a\u043a\u043e\u0432\u043e\u0434\u0438\u0442\u0435\u043b"},
gel(){return"\u041c\u043e\u043b\u044f, \u0432\u044a\u0432\u0435\u0434\u0435\u0442\u0435 \u043f\u043e\u0442\u0440\u0435\u0431\u0438\u0442\u0435\u043b\u044f \u0438 \u043f\u0430\u0440\u043e\u043b\u0430\u0442\u0430 \u043f\u0440\u0430\u0432\u0438\u043b\u043d\u043e"},
