gdB(){return"\u0421\u043e\u0440\u0442\u0438\u0440\u0430\u0439 \u043f\u043e \u0437\u0430\u0433\u043b\u0430\u0432\u0438\u0435"},
gdA(){return"\u0421\u043e\u0440\u0442\u0438\u0440\u0430\u0439 \u043f\u043e \u043e\u043f\u0438\u0441\u0430\u043d\u0438\u0435"},
gey(){return"\u0421\u043e\u0440\u0442\u0438\u0440\u0430\u0439 \u043f\u043e \u0438\u043c\u0435"},
gez(){return"\u0421\u043e\u0440\u0442\u0438\u0440\u0430\u0439 \u043f\u043e \u043f\u043e\u0437\u0438\u0446\u0438\u044f"},
gdz(){return"\u041d\u044f\u043c\u0430 \u043d\u0430\u043c\u0435\u0440\u0435\u043d\u043e"},
gcU(a){return"\u0422\u044a\u0440\u0441\u0435\u043d\u0435"},
ge4(){return"bg"},
gef(){return"\u0421\u0432\u044a\u0440\u0436\u0438 \u0441\u0435"},
