geE(a){return"\u0412\u0435\u0440\u0441\u0438\u044f"},
gei(a){return"\u0418\u0437\u0442\u0435\u0433\u043b\u0438"},
gek(){return"\u0422\u043e\u0437\u0438 \u0438\u043c\u0435\u0439\u043b \u043d\u0435 \u0435 \u0432\u0430\u043b\u0438\u0434\u0435\u043d"},
ged(){return"\u0414\u043e\u0431\u0430\u0432\u0435\u0442\u0435 \u0438\u043c\u0435\u0439\u043b"},
geF(){return"\u041a\u0430\u043a\u0432\u043e \u0435 Edhomy AI \u0435\u0437\u0438\u0446\u0438?"},
gej(){return"Edhomy AI languages \u0435 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435, \u0432 \u043a\u043e\u0435\u0442\u043e \u043c\u043e\u0436\u0435\u0442\u0435 \u0434\u0430 \u043d\u0430\u0443\u0447\u0438\u0442\u0435 \u0435\u0437\u0438\u043a \u0441 \u0418\u0418. \u0422\u043e \u043f\u0440\u0435\u0434\u043b\u0430\u0433\u0430 \u0418\u0418 \u0443\u0447\u0438\u0442\u0435\u043b \u0437\u0430 \u043f\u0440\u0430\u043a\u0442\u0438\u043a\u0430 \u043d\u0430 \u043f\u0440\u043e\u0438\u0437\u043d\u043e\u0448\u0435\u043d\u0438\u0435 \u0438 \u043a\u0443\u0440\u0441 \u0437\u0430 \u0440\u0430\u0437\u043a\u0430\u0437\u0432\u0430\u043d\u0435 \u043d\u0430 \u0438\u0441\u0442\u043e\u0440\u0438\u0438 \u0441 100 \u0443\u0440\u043e\u043a\u0430, \u043a\u043e\u0438\u0442\u043e \u0434\u0430 \u0432\u0438 \u043f\u043e\u043c\u043e\u0433\u043d\u0430\u0442 \u0434\u0430 \u043e\u0432\u043b\u0430\u0434\u0435\u0435\u0442\u0435 \u0435\u0437\u0438\u043a\u0430."},
gee(){return"\u041c\u043e\u0433\u0430 \u043b\u0438 \u0434\u0430 \u043d\u0430\u0443\u0447\u0430 \u0435\u0437\u0438\u043a?"},
geB(){return"\u0414\u0430, \u043c\u043e\u0436\u0435\u0442\u0435. \u0421\u044a\u0442\u0440\u0443\u0434\u043d\u0438\u0447\u0438\u043c \u0441 \u0435\u043a\u0441\u043f\u0435\u0440\u0442\u0438, \u043a\u043e\u0438\u0442\u043e \u0437\u043d\u0430\u044f\u0442 \u043d\u0430\u0439-\u0434\u043e\u0431\u0440\u0438\u0442\u0435 \u043c\u0435\u0442\u043e\u0434\u0438 \u0437\u0430 \u0443\u0447\u0435\u043d\u0435 \u0447\u0440\u0435\u0437 \u043c\u0443\u043b\u0442\u0438\u043c\u0435\u0434\u0438\u0439\u043d\u0438 \u043a\u0443\u0440\u0441\u043e\u0432\u0435."},
gev(){return"\u0422\u0430\u0437\u0438 \u043f\u043b\u0430\u0442\u0444\u043e\u0440\u043c\u0430 \u043b\u0438 \u0435 \u0441\u0438\u0433\u0443\u0440\u043d\u0430?"},
geu(){return"\u041d\u0435 \u043f\u0440\u043e\u0434\u0430\u0432\u0430\u043c\u0435 \u0432\u0430\u0448\u0438\u0442\u0435 \u0434\u0430\u043d\u043d\u0438 \u043d\u0430 \u0442\u0440\u0435\u0442\u0438 \u0441\u0442\u0440\u0430\u043d\u0438. \u041f\u0430\u0440\u043e\u043b\u0438\u0442\u0435 \u0438 \u0438\u043c\u0435\u0439\u043b\u0438\u0442\u0435 \u0441\u0430 \u043d\u0430\u043f\u044a\u043b\u043d\u043e \u043a\u0440\u0438\u043f\u0442\u0438\u0440\u0430\u043d\u0438. \u0421\u0430\u043c\u043e \u0432\u0438\u0435 \u043c\u043e\u0436\u0435\u0442\u0435 \u0434\u0430 \u0434\u043e\u043a\u043b\u0430\u0434\u0432\u0430\u0442\u0435 \u0432\u0441\u044f\u043a\u0430\u043a\u0432\u0438 \u043f\u043e\u0434\u043e\u0437\u0440\u0438\u0442\u0435\u043b\u043d\u0438 \u0441\u0438\u0442\u0443\u0430\u0446\u0438\u0438, \u043a\u043e\u0438\u0442\u043e \u043c\u043e\u0433\u0430\u0442 \u0434\u0430 \u043f\u043e\u0432\u043b\u0438\u044f\u044f\u0442 \u043d\u0430 \u0432\u0430\u0448\u0430\u0442\u0430 \u0441\u0438\u0433\u0443\u0440\u043d\u043e\u0441\u0442, \u0438 \u0435\u043a\u0438\u043f\u044a\u0442 \u0437\u0430 \u043f\u043e\u0434\u0434\u0440\u044a\u0436\u043a\u0430 \u0449\u0435 \u0441\u0435 \u0441\u0432\u044a\u0440\u0436\u0435 \u0441 \u0432\u0430\u0441."},
gep(){return"\u041a\u0430\u043a \u0434\u0430 \u043d\u0430\u0443\u0447\u0430 \u0432 \u0442\u043e\u0432\u0430 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435?"},
geh(){return"\u041c\u043e\u0436\u0435\u0442\u0435 \u0434\u0430 \u0441\u043b\u0435\u0434\u0432\u0430\u0442\u0435 \u0440\u044a\u043a\u043e\u0432\u043e\u0434\u0435\u043d\u0438 \u043a\u0443\u0440\u0441\u043e\u0432\u0435, \u0434\u0430 \u043f\u0440\u0430\u043a\u0442\u0438\u043a\u0443\u0432\u0430\u0442\u0435 \u0441 \u0418\u0418 \u0443\u0447\u0438\u0442\u0435\u043b \u0438 \u0434\u0430 \u043f\u0440\u043e\u0434\u044a\u043b\u0436\u0438\u0442\u0435 \u0434\u0430 \u043d\u0430\u043f\u0440\u0435\u0434\u0432\u0430\u0442\u0435, \u0437\u0430 \u0434\u0430 \u043f\u0440\u0435\u043e\u0434\u043e\u043b\u0435\u0435\u0442\u0435 \u043d\u0438\u0432\u043e \u043d\u0430 \u043e\u0446\u0435\u043b\u044f\u0432\u0430\u043d\u0435."},
